INSERT INTO quiz_questions (id, lesson_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES
(gen_random_uuid(), 'renal-filtration', 'What is the primary function of the Loop of Henle?', 'Reabsorption of water and sodium', 'Secretion of potassium', 'Filtration of blood', 'Synthesis of renin', 'A', 'The loop of Henle is responsible for creating a concentration gradient in the medulla to allow for water reabsorption.', 'MEDIUM'),
(gen_random_uuid(), 'endocrine-hormones', 'Which hormone is responsible for lowering blood glucose levels?', 'Glucagon', 'Insulin', 'Cortisol', 'Epinephrine', 'B', 'Insulin facilitates the cellular uptake of glucose, thereby lowering blood glucose levels.', 'EASY'),
(gen_random_uuid(), 'cardiac-cycle', 'During the cardiac cycle, when do the AV valves close?', 'Beginning of ventricular systole', 'End of ventricular systole', 'Beginning of atrial systole', 'During diastole', 'A', 'The AV valves close when ventricular pressure exceeds atrial pressure at the beginning of ventricular systole, creating the first heart sound (S1).', 'MEDIUM'),
(gen_random_uuid(), 'action-potential', 'What is the normal resting membrane potential of a typical neuron?', '-90 mV', '-70 mV', '+30 mV', '0 mV', 'B', 'A typical neuron has a resting membrane potential of approximately -70mV, maintained by the Na+/K+ ATPase pump and leak channels.', 'EASY'),
(gen_random_uuid(), 'motor-system', 'Which part of the brain is primarily responsible for coordinating voluntary movements?', 'Cerebrum', 'Cerebellum', 'Medulla oblongata', 'Hypothalamus', 'B', 'The cerebellum coordinates voluntary movements such as posture, balance, coordination, and speech.', 'EASY'),
(gen_random_uuid(), 'gas-exchange', 'What is the primary site of gas exchange in the lungs?', 'Bronchi', 'Trachea', 'Alveoli', 'Bronchioles', 'C', 'Alveoli provide a large surface area and thin membrane for efficient gas exchange between air and blood.', 'EASY'),
(gen_random_uuid(), 'skeletal-muscle', 'Which ion is essential for muscle contraction to expose the myosin binding sites on actin?', 'Sodium', 'Potassium', 'Calcium', 'Magnesium', 'C', 'Calcium binds to troponin, causing a conformational change that moves tropomyosin away from the myosin-binding sites on actin.', 'MEDIUM'),
(gen_random_uuid(), 'hemostasis', 'Which vitamin is crucial for blood clotting?', 'Vitamin A', 'Vitamin B12', 'Vitamin C', 'Vitamin K', 'D', 'Vitamin K is required for the synthesis of coagulation factors II, VII, IX, and X.', 'EASY'),
(gen_random_uuid(), 'digestion-absorption', 'What enzyme is responsible for the initial digestion of carbohydrates in the mouth?', 'Pepsin', 'Lipase', 'Amylase', 'Trypsin', 'C', 'Salivary amylase initiates carbohydrate digestion in the mouth.', 'EASY'),
(gen_random_uuid(), 'blood-composition', 'Which hormone stimulates the production of red blood cells?', 'Erythropoietin', 'Aldosterone', 'Thyroxine', 'Prolactin', 'A', 'Erythropoietin (EPO) is produced by the kidneys in response to hypoxia and stimulates red blood cell production in the bone marrow.', 'EASY'),
(gen_random_uuid(), 'acid-base', 'What is the primary buffer system in the extracellular fluid?', 'Phosphate buffer', 'Bicarbonate buffer', 'Protein buffer', 'Hemoglobin buffer', 'B', 'The bicarbonate-carbonic acid system is the primary buffer of the ECF.', 'MEDIUM'),
(gen_random_uuid(), 'special-senses-vision', 'Which photoreceptors are responsible for color vision?', 'Rods', 'Cones', 'Bipolar cells', 'Ganglion cells', 'B', 'Cones function in bright light and are responsible for color vision and high visual acuity.', 'EASY'),
(gen_random_uuid(), 'gi-secretions', 'Which cells in the stomach secrete hydrochloric acid (HCl)?', 'Chief cells', 'Parietal cells', 'G cells', 'Mucous neck cells', 'B', 'Parietal (oxyntic) cells in the gastric glands secrete HCl and intrinsic factor.', 'MEDIUM'),
(gen_random_uuid(), 'cardiac-output', 'According to the Frank-Starling law, increased preload leads to:', 'Decreased stroke volume', 'Increased stroke volume', 'Decreased heart rate', 'Increased heart rate', 'B', 'Increased end-diastolic volume stretches the ventricular muscle fibers, increasing the force of contraction and stroke volume.', 'HARD'),
(gen_random_uuid(), 'respiratory-mechanics', 'Surfactant in the lungs serves to:', 'Increase surface tension', 'Decrease surface tension', 'Increase airway resistance', 'Decrease lung compliance', 'B', 'Surfactant reduces surface tension in the alveoli, preventing their collapse and increasing lung compliance.', 'MEDIUM'),
(gen_random_uuid(), 'renal-filtration', 'Which substance is freely filtered by the glomerulus but neither reabsorbed nor secreted?', 'Glucose', 'Urea', 'Inulin', 'Creatinine', 'C', 'Inulin is an exogenous plant polysaccharide used to measure GFR because it is freely filtered and not reabsorbed or secreted.', 'HARD'),
(gen_random_uuid(), 'endocrine-hormones', 'Where is antidiuretic hormone (ADH) synthesized?', 'Anterior pituitary', 'Posterior pituitary', 'Hypothalamus', 'Adrenal cortex', 'C', 'ADH is synthesized in the supraoptic and paraventricular nuclei of the hypothalamus and stored in the posterior pituitary.', 'MEDIUM'),
(gen_random_uuid(), 'smooth-muscle', 'Unlike skeletal muscle, smooth muscle contraction is regulated by:', 'Troponin', 'Calmodulin', 'Tropomyosin', 'T-tubules', 'B', 'In smooth muscle, calcium binds to calmodulin, which activates myosin light-chain kinase to initiate contraction.', 'HARD'),
(gen_random_uuid(), 'cns-synapse', 'Which neurotransmitter is typically inhibitory in the central nervous system?', 'Glutamate', 'Acetylcholine', 'GABA', 'Norepinephrine', 'C', 'Gamma-aminobutyric acid (GABA) is the primary inhibitory neurotransmitter in the brain.', 'MEDIUM'),
(gen_random_uuid(), 'blood-groups', 'A person with type O blood has which antibodies in their plasma?', 'Anti-A only', 'Anti-B only', 'Both Anti-A and Anti-B', 'Neither Anti-A nor Anti-B', 'C', 'Type O individuals lack A and B antigens on their RBCs and possess both anti-A and anti-B antibodies in their plasma.', 'MEDIUM');
